insert into public.content_documents (key, content, active)
values
  ('workouts', $content${"exercicios":[{"id":"e01","nome":"Agachamento livre","grupo":"Pernas","dicas":"Pés na largura do quadril. Os joelhos acompanham a ponta dos pés. Desça como se fosse sentar, peito aberto.","erros":"Joelhos entrando pra dentro; tirar o calcanhar do chão; curvar as costas","alternativa":"e02","video":"","videoLink":"","exemplo":true},{"id":"e02","nome":"Sentar e levantar do banco","grupo":"Pernas","dicas":"Use um banco firme. Sente sem desabar e levante empurrando o chão com os calcanhares.","erros":"Desabar no banco; usar impulso do tronco","alternativa":"","video":"","videoLink":"","exemplo":true},{"id":"e03","nome":"Leg press 45°","grupo":"Pernas","dicas":"Lombar sempre encostada. Não estique os joelhos por completo no fim do movimento.","erros":"Tirar a lombar do encosto; travar os joelhos no final","alternativa":"e01","video":"","videoLink":"","exemplo":true},{"id":"e04","nome":"Afundo alternado","grupo":"Pernas","dicas":"Passo largo, tronco reto. O joelho de trás desce em direção ao chão.","erros":"Joelho da frente passando muito da ponta do pé; tronco caindo pra frente","alternativa":"e05","video":"","videoLink":"","exemplo":true},{"id":"e05","nome":"Afundo estático com apoio","grupo":"Pernas","dicas":"Segure na parede ou numa cadeira. Suba e desça sem trocar a posição dos pés.","erros":"Ir rápido e perder o equilíbrio; joelho de trás batendo no chão","alternativa":"","video":"","videoLink":"","exemplo":true},{"id":"e06","nome":"Elevação de quadril com barra","grupo":"Glúteos","dicas":"Queixo levemente pra baixo. Suba contraindo o glúteo e segure 1 segundo no topo.","erros":"Arquear a lombar no topo; empurrar com a ponta dos pés","alternativa":"e07","video":"","videoLink":"","exemplo":true},{"id":"e07","nome":"Ponte de glúteo no chão","grupo":"Glúteos","dicas":"Pés firmes perto do quadril. Suba devagar e desça controlando.","erros":"Subir arqueando a lombar; pés longe demais do quadril","alternativa":"","video":"","videoLink":"","exemplo":true},{"id":"e08","nome":"Cadeira abdutora","grupo":"Glúteos","dicas":"Tronco levemente inclinado à frente. Abra controlando, sem soltar o peso.","erros":"Soltar o peso de uma vez na volta; usar impulso","alternativa":"e09","video":"","videoLink":"","exemplo":true},{"id":"e09","nome":"Abdução com elástico deitada","grupo":"Glúteos","dicas":"Deitada de lado, quadril empilhado. Suba a perna sem girar o pé pra cima.","erros":"Girar o quadril pra trás; subir a perna rápido demais","alternativa":"","video":"","videoLink":"","exemplo":true},{"id":"e10","nome":"Remada baixa na polia","grupo":"Costas","dicas":"Puxe levando os cotovelos pra trás e aproximando as escápulas.","erros":"Encolher os ombros; jogar o tronco pra trás","alternativa":"e11","video":"","videoLink":"","exemplo":true},{"id":"e11","nome":"Remada com elástico","grupo":"Costas","dicas":"Elástico preso na altura do peito. Puxe sem encolher os ombros.","erros":"Ombros perto das orelhas; soltar o elástico sem controle","alternativa":"","video":"","videoLink":"","exemplo":true},{"id":"e12","nome":"Puxada frontal","grupo":"Costas","dicas":"Puxe a barra até a altura do queixo, peito aberto, sem jogar o corpo pra trás.","erros":"Puxar atrás da nuca; balançar o corpo","alternativa":"e11","video":"","videoLink":"","exemplo":true},{"id":"e13","nome":"Supino com halteres","grupo":"Peito","dicas":"Halteres na linha do peito. Desça até os cotovelos ficarem um pouco abaixo do banco.","erros":"Descer rápido demais; abrir os cotovelos a 90 graus","alternativa":"e14","video":"","videoLink":"","exemplo":true},{"id":"e14","nome":"Flexão com joelhos apoiados","grupo":"Peito","dicas":"Mãos um pouco mais abertas que os ombros. Corpo alinhado do joelho à cabeça.","erros":"Quadril caindo; cabeça projetada pra frente","alternativa":"","video":"","videoLink":"","exemplo":true},{"id":"e15","nome":"Desenvolvimento com halteres","grupo":"Ombros","dicas":"Sentada, costas apoiadas. Suba sem arquear a lombar.","erros":"Arquear a lombar; descer o halter rápido demais","alternativa":"","video":"","videoLink":"","exemplo":true},{"id":"e16","nome":"Elevação lateral","grupo":"Ombros","dicas":"Cotovelos levemente flexionados. Suba até a linha dos ombros, sem impulso.","erros":"Subir acima da linha dos ombros; balançar o tronco","alternativa":"","video":"","videoLink":"","exemplo":true},{"id":"e17","nome":"Prancha","grupo":"Core","dicas":"Cotovelos abaixo dos ombros, abdômen firme, quadril alinhado. Respire.","erros":"Quadril alto demais ou caído; prender a respiração","alternativa":"","video":"","videoLink":"","exemplo":true},{"id":"e18","nome":"Abdominal infra","grupo":"Core","dicas":"Lombar colada no chão. Suba as pernas sem embalar.","erros":"Tirar a lombar do chão; embalar as pernas","alternativa":"","video":"","videoLink":"","exemplo":true},{"id":"e19","nome":"Levantamento terra romeno","grupo":"Posterior","dicas":"Joelhos levemente flexionados. Leve o quadril pra trás com a coluna neutra.","erros":"Arredondar as costas; dobrar demais os joelhos","alternativa":"e07","video":"","videoLink":"","exemplo":true},{"id":"e20","nome":"Agachamento búlgaro","grupo":"Pernas","dicas":"Pé de trás apoiado no banco. Desça na vertical, tronco levemente inclinado.","erros":"Pé da frente perto demais do banco; joelho entrando","alternativa":"e04","video":"","videoLink":"","exemplo":true},{"id":"e21","nome":"Polichinelo","grupo":"Cardio","dicas":"Aterrisse com os joelhos levemente dobrados. Pode fazer sem salto.","erros":"Aterrissar com as pernas esticadas; ombros tensos","alternativa":"","video":"","videoLink":"","exemplo":true},{"id":"e22","nome":"Rosca direta","grupo":"Braços","dicas":"Cotovelos colados ao corpo. Suba e desça sem balançar o tronco.","erros":"Balançar o tronco; afastar os cotovelos do corpo","alternativa":"","video":"","videoLink":"","exemplo":true}],"programas":[{"id":"p1","nome":"Academia · Iniciante","modalidade":"academia","niveis":["iniciante"],"inicio":"2026-11-02","exemplo":true,"treinos":[{"